import pygame
import random
import sys

WIDTH, HEIGHT = 480, 640
FPS = 60
PLAYER_SPEED = 5
BULLET_SPEED = 8
ALIEN_BULLET_SPEED = 4
BASE_ALIEN_SPEED = 1.0
DESCENT = 18
ROWS, COLS = 4, 8
ALIEN_W, ALIEN_H = 32, 22
SPACING_X, SPACING_Y = 44, 38
PLAYER_W, PLAYER_H = 32, 24
PLAYER_Y = HEIGHT - 48
LIVES = 3
ROW_POINTS = [30, 20, 20, 10]
ROW_COLORS = [(0, 220, 100), (0, 200, 220), (240, 220, 60), (240, 100, 200)]

pygame.init()
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Space Invaders")
clock = pygame.time.Clock()
font = pygame.font.SysFont(None, 26)
big_font = pygame.font.SysFont(None, 52)
STARS = [(random.randint(0, WIDTH - 1), random.randint(0, HEIGHT - 1)) for _ in range(80)]


def new_game():
    aliens = []
    for r in range(ROWS):
        for c in range(COLS):
            aliens.append({"x": 50 + c * SPACING_X, "y": 70 + r * SPACING_Y,
                           "row": r, "alive": True})
    return {"px": WIDTH // 2 - PLAYER_W // 2, "bullets": [], "ebullets": [], "aliens": aliens,
            "dir": 1, "score": 0, "lives": LIVES, "state": "play", "cooldown": 0, "fire": 60}


def draw_ship(x):
    pygame.draw.polygon(screen, (80, 255, 120),
                        [(x + PLAYER_W // 2, PLAYER_Y), (x + PLAYER_W, PLAYER_Y + 16),
                         (x + PLAYER_W, PLAYER_Y + PLAYER_H), (x, PLAYER_Y + PLAYER_H),
                         (x, PLAYER_Y + 16)])
    pygame.draw.rect(screen, (255, 200, 60), (x + PLAYER_W // 2 - 2, PLAYER_Y + 6, 4, 8))


def draw_alien(a):
    x, y, col = a["x"], a["y"], ROW_COLORS[a["row"]]
    pygame.draw.rect(screen, col, (x, y, ALIEN_W, ALIEN_H), border_radius=8)
    pygame.draw.rect(screen, (20, 20, 20), (x + 6, y + 6, 6, 6))
    pygame.draw.rect(screen, (20, 20, 20), (x + ALIEN_W - 12, y + 6, 6, 6))
    pygame.draw.rect(screen, col, (x + 7, y + ALIEN_H, 5, 5))
    pygame.draw.rect(screen, col, (x + ALIEN_W - 12, y + ALIEN_H, 5, 5))


def update(g):
    keys = pygame.key.get_pressed()
    if keys[pygame.K_LEFT] or keys[pygame.K_a]:
        g["px"] -= PLAYER_SPEED
    if keys[pygame.K_RIGHT] or keys[pygame.K_d]:
        g["px"] += PLAYER_SPEED
    g["px"] = max(0, min(WIDTH - PLAYER_W, g["px"]))
    g["cooldown"] -= 1

    for b in g["bullets"]:
        b[1] -= BULLET_SPEED
    g["bullets"] = [b for b in g["bullets"] if b[1] > 40]
    for b in g["ebullets"]:
        b[1] += ALIEN_BULLET_SPEED
    g["ebullets"] = [b for b in g["ebullets"] if b[1] < HEIGHT]

    alive_count = sum(1 for a in g["aliens"] if a["alive"])
    speed = BASE_ALIEN_SPEED + (ROWS * COLS - alive_count) * 0.03
    hit_edge = False
    for a in g["aliens"]:
        if a["alive"]:
            a["x"] += g["dir"] * speed
            if a["x"] <= 0 or a["x"] + ALIEN_W >= WIDTH:
                hit_edge = True
    if hit_edge:
        g["dir"] *= -1
        for a in g["aliens"]:
            if a["alive"]:
                a["y"] += DESCENT

    g["fire"] -= 1
    if g["fire"] <= 0:
        alive = [a for a in g["aliens"] if a["alive"]]
        if alive:
            s = random.choice(alive)
            g["ebullets"].append([s["x"] + ALIEN_W // 2, s["y"] + ALIEN_H])
        g["fire"] = random.randint(30, 70)

    for b in g["bullets"]:
        for a in g["aliens"]:
            if (a["alive"] and a["x"] - 2 <= b[0] <= a["x"] + ALIEN_W + 2
                    and a["y"] - 2 <= b[1] <= a["y"] + ALIEN_H + 2):
                a["alive"] = False
                g["score"] += ROW_POINTS[a["row"]]
                b[1] = -10
                break

    for b in g["ebullets"]:
        if g["px"] <= b[0] <= g["px"] + PLAYER_W and PLAYER_Y <= b[1] <= PLAYER_Y + PLAYER_H:
            b[1] = HEIGHT + 10
            g["lives"] -= 1
            if g["lives"] <= 0:
                g["state"] = "over"

    for a in g["aliens"]:
        if a["alive"] and a["y"] + ALIEN_H >= PLAYER_Y:
            g["state"] = "over"

    if all(not a["alive"] for a in g["aliens"]):
        g["state"] = "win"


def draw(g):
    screen.fill((8, 10, 28))
    for sx, sy in STARS:
        screen.set_at((sx, sy), (200, 200, 255))
    for a in g["aliens"]:
        if a["alive"]:
            draw_alien(a)
    for b in g["bullets"]:
        pygame.draw.rect(screen, (255, 255, 120), (b[0] - 2, b[1] - 8, 4, 12))
    for b in g["ebullets"]:
        pygame.draw.rect(screen, (255, 90, 90), (b[0] - 2, b[1], 4, 10))
    if g["state"] in ("play", "over"):
        draw_ship(g["px"])
    screen.blit(font.render(f"Score: {g['score']}", True, (255, 255, 255)), (10, 8))
    screen.blit(font.render(f"Lives: {g['lives']}", True, (255, 255, 255)), (WIDTH - 100, 8))
    if g["state"] == "over":
        msg = big_font.render("GAME OVER", True, (255, 80, 80))
        screen.blit(msg, (WIDTH // 2 - msg.get_width() // 2, HEIGHT // 2 - 40))
    elif g["state"] == "win":
        msg = big_font.render("YOU WIN!", True, (120, 255, 120))
        screen.blit(msg, (WIDTH // 2 - msg.get_width() // 2, HEIGHT // 2 - 40))
    if g["state"] != "play":
        tip = font.render(f"Final Score: {g['score']}  -  Press ENTER to restart", True, (255, 255, 255))
        screen.blit(tip, (WIDTH // 2 - tip.get_width() // 2, HEIGHT // 2 + 20))
    pygame.display.flip()


def main():
    g = new_game()
    while True:
        for e in pygame.event.get():
            if e.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            if e.type == pygame.KEYDOWN and e.key == pygame.K_RETURN and g["state"] != "play":
                g = new_game()
            if (e.type == pygame.KEYDOWN and e.key == pygame.K_SPACE and g["state"] == "play"
                    and g["cooldown"] <= 0):
                g["bullets"].append([g["px"] + PLAYER_W // 2, PLAYER_Y - 4])
                g["cooldown"] = 18
        if g["state"] == "play":
            update(g)
        draw(g)
        clock.tick(FPS)


if __name__ == "__main__":
    main()
